window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bdc0fe4542be941a"]={"versions": [{"id": "FIG-bdc0fe4542be941a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Hardware-Sensor-/Aktorelementen und deren Port-Anbindungen im Kontext des AUTOSAR ECU Resource Templates (Hardware-Beschreibungsebene).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert Spezialisierungen und Assoziationen rund um Hardware-Elemente und Hardware-Ports:</p>\n<ul class=\"fig-list\">\n<li><strong><code>SensorActuatorHW</code></strong> (Stereotyp/Spezialisierung von <code>HWElement</code>, kursiv/abstrakt):</li>\n<li>Attribute: <code>type: String</code>, <code>accuracy: Float</code>, <code>resolution: Float [0..1]</code>.</li>\n<li>Komposition zu <code>TimeRange</code> über die Rolle <code>+cycleTime</code> mit Multiplizität <code>0..1</code>.</li>\n<li>Abhängigkeiten / Port-Verknüpfungen (gestrichelte Pfeile):</li>\n<li>Abhängigkeit zu <code>HWPort</code> mit der Beschriftung <code>Technical Signal HW Port</code>.</li>\n<li>Abhängigkeit zu <code>PeripheralHWPort</code>.</li>\n<li>Abhängigkeit zu <code>CommunicationHWPort</code>.</li>\n<li>Generalisierungsbasis für die konkreten Hardware-Klassen:</li>\n<li><code>ActuatorHW</code></li>\n<li><code>SensorHW</code></li>\n<li><code>DisplayHW</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>ActuatorHW</code></strong>:</li>\n<li>Erbt von <code>SensorActuatorHW</code>.</li>\n<li>Besitzt eine gerichtete Abhängigkeit (gestrichelter Pfeil) zu <code>PowerDriverHWPort</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>TimeRange</code></strong>:</li>\n<li>Attribute: <code>min: Float [0..1]</code>, <code>max: Float</code>, <code>typical: Float [0..1]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Port-Hierarchie (<code>HWPort</code>, erbt von <code>Identifiable</code>):</strong></li>\n<li><code>HWPort</code> fungiert als Basisklasse für hardwarebezogene Schnittstellen.</li>\n<li><code>PowerDriverHWPort</code> erbt direkt von <code>HWPort</code>.</li>\n<li><code>PeripheralHWPort</code> erbt direkt von <code>HWPort</code>.</li>\n<li><code>CommunicationHWPort</code> erbt von <code>PeripheralHWPort</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung von Laufzeit- oder Sequenzverhalten. Die Spezifikation beschreibt Deklarationsstrukturen zur statischen Beschreibung von Hardware-Ressourcen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung legt verbindliche Metaklassen für die Beschreibung von Sensor-, Aktor- und Display-Hardwarekomponenten fest:</p>\n<ul class=\"fig-list\">\n<li><code>SensorActuatorHW</code> erfordert zwingend Angaben zu <code>type</code> und <code>accuracy</code>, während <code>resolution</code> optional ist.</li>\n<li>Die Zykluszeit (<code>+cycleTime</code>) kann optional über eine <code>TimeRange</code> strukturiert mit Minimal-, Maximal- und typischem Wert angegeben werden, wobei <code>max</code> obligatorisch ist.</li>\n<li>Spezifische Hardware-Ports (<code>PowerDriverHWPort</code>, <code>PeripheralHWPort</code>, <code>CommunicationHWPort</code>) müssen den typisierten Verbindungsanforderungen von Sensoren und Aktoren entsprechen; <code>ActuatorHW</code> bindet explizit an Leistungs-Treiberports (<code>PowerDriverHWPort</code>) an.</li>\n</ul>"}, {"id": "FIG-9fe16b23eb5d07a5", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Hardware-Sensor-/Aktorelementen und deren Port-Anbindungen im Kontext des AUTOSAR ECU Resource Templates (Hardware-Beschreibungsebene).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert Spezialisierungen und Assoziationen rund um Hardware-Elemente und Hardware-Ports:</p>\n<ul class=\"fig-list\">\n<li><strong><code>SensorActuatorHW</code></strong> (Stereotyp/Spezialisierung von <code>HWElement</code>, kursiv/abstrakt):</li>\n<li>Attribute: <code>type: String</code>, <code>accuracy: Float</code>, <code>resolution: Float [0..1]</code>.</li>\n<li>Komposition zu <code>TimeRange</code> über die Rolle <code>+cycleTime</code> mit Multiplizität <code>0..1</code>.</li>\n<li>Abhängigkeiten / Port-Verknüpfungen (gestrichelte Pfeile):</li>\n<li>Abhängigkeit zu <code>HWPort</code> mit der Beschriftung <code>Technical Signal HW Port</code>.</li>\n<li>Abhängigkeit zu <code>PeripheralHWPort</code>.</li>\n<li>Abhängigkeit zu <code>CommunicationHWPort</code>.</li>\n<li>Generalisierungsbasis für die konkreten Hardware-Klassen:</li>\n<li><code>ActuatorHW</code></li>\n<li><code>SensorHW</code></li>\n<li><code>DisplayHW</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>ActuatorHW</code></strong>:</li>\n<li>Erbt von <code>SensorActuatorHW</code>.</li>\n<li>Besitzt eine gerichtete Abhängigkeit (gestrichelter Pfeil) zu <code>PowerDriverHWPort</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>TimeRange</code></strong>:</li>\n<li>Attribute: <code>min: Float [0..1]</code>, <code>max: Float</code>, <code>typical: Float [0..1]</code>.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Port-Hierarchie (<code>HWPort</code>, erbt von <code>Identifiable</code>):</strong></li>\n<li><code>HWPort</code> fungiert als Basisklasse für hardwarebezogene Schnittstellen.</li>\n<li><code>PowerDriverHWPort</code> erbt direkt von <code>HWPort</code>.</li>\n<li><code>PeripheralHWPort</code> erbt direkt von <code>HWPort</code>.</li>\n<li><code>CommunicationHWPort</code> erbt von <code>PeripheralHWPort</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Darstellung von Laufzeit- oder Sequenzverhalten. Die Spezifikation beschreibt Deklarationsstrukturen zur statischen Beschreibung von Hardware-Ressourcen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung legt verbindliche Metaklassen für die Beschreibung von Sensor-, Aktor- und Display-Hardwarekomponenten fest:</p>\n<ul class=\"fig-list\">\n<li><code>SensorActuatorHW</code> erfordert zwingend Angaben zu <code>type</code> und <code>accuracy</code>, während <code>resolution</code> optional ist.</li>\n<li>Die Zykluszeit (<code>+cycleTime</code>) kann optional über eine <code>TimeRange</code> strukturiert mit Minimal-, Maximal- und typischem Wert angegeben werden, wobei <code>max</code> obligatorisch ist.</li>\n<li>Spezifische Hardware-Ports (<code>PowerDriverHWPort</code>, <code>PeripheralHWPort</code>, <code>CommunicationHWPort</code>) müssen den typisierten Verbindungsanforderungen von Sensoren und Aktoren entsprechen; <code>ActuatorHW</code> bindet explizit an Leistungs-Treiberports (<code>PowerDriverHWPort</code>) an.</li>\n</ul>"}], "trans": [{"from": "FIG-bdc0fe4542be941a", "to": "FIG-9fe16b23eb5d07a5", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
